from collections import deque

def comps(grid):
 h,w=len(grid),len(grid[0]); seen=set(); out=[]
 for r in range(h):
  for c in range(w):
   if (r,c) in seen: continue
   col=grid[r][c]; q=deque([(r,c)]); seen.add((r,c)); cells=[]
   while q:
    y,x=q.popleft();cells.append((y,x))
    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
     z=(y+dy,x+dx)
     if 0<=z[0]<h and 0<=z[1]<w and z not in seen and grid[z[0]][z[1]]==col: seen.add(z);q.append(z)
   rs=[y for y,x in cells]; cs=[x for y,x in cells]; area=(max(rs)-min(rs)+1)*(max(cs)-min(cs)+1)
   out.append((len(cells),col,area,len(cells)/area,(min(rs),max(rs),min(cs),max(cs))))
 return sorted(out,reverse=True)
